export function BookingWidget({
  serviceName = "{{serviceName}}",
  selectedDate = "{{selectedDate}}",
  period = "{{period}}",
  accent = "{{accent}}",
  showPrice = {{showPrice}},
}) {
  const slots = ["9:00", "10:30", "12:00"];
  return (
    <div style={{ font: "16px system-ui, sans-serif", color: "#241430", maxWidth: 300, border: "1px solid #24143022",
      borderRadius: 14, padding: 18, background: "#FAF7F2" }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline", marginBottom: 12 }}>
        <h3 style={{ margin: 0, fontSize: 17, fontWeight: 700 }}>{serviceName}</h3>
        <span style={{ fontSize: 13, color: "#241430aa" }}>{selectedDate}</span>
      </div>
      <span style={{ display: "block", fontSize: 11, fontWeight: 700, textTransform: "uppercase",
        letterSpacing: "0.05em", color: "#24143088", marginBottom: 8 }}>{period}</span>
      <div style={{ display: "flex", gap: 8, flexWrap: "wrap", marginBottom: 12, opacity: period === "Evening" ? 0.92 : 1 }}>
        {slots.map((slot, i) => (
          <button key={slot} type="button" style={{ border: `1.5px solid ${accent}`,
            background: i === 1 ? accent : "transparent", color: i === 1 ? "#FAF7F2" : accent,
            padding: "6px 12px", borderRadius: 8, font: "600 13px system-ui, sans-serif", cursor: "pointer" }}>
            {slot}
          </button>
        ))}
      </div>
      {showPrice && <p style={{ margin: 0, fontSize: 13, color: "#241430cc" }}>From <strong>$45</strong> per session</p>}
    </div>
  );
}
